package com.dramastudio.engine;
import com.fasterxml.jackson.databind.ObjectMapper; import java.io.IOException; import java.time.Instant; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicLong; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@Component public class RunEventHub {
 private final Map<String,List<SseEmitter>> clients=new ConcurrentHashMap<>();private final Map<String,AtomicLong> sequences=new ConcurrentHashMap<>();private final JdbcTemplate jdbc;private final ObjectMapper json;
 public RunEventHub(JdbcTemplate j,ObjectMapper o){jdbc=j;json=o;}
 public SseEmitter subscribe(String runId,long after){SseEmitter e=new SseEmitter(0L);clients.computeIfAbsent(runId,k->new CopyOnWriteArrayList<>()).add(e);Runnable remove=()->clients.getOrDefault(runId,List.of()).remove(e);e.onCompletion(remove);e.onTimeout(remove);try{for(var row:jdbc.queryForList("select event_id,event_type,payload_json from run_events where workflow_run_id=? and event_id>? order by event_id",runId,after))e.send(SseEmitter.event().id(row.get("event_id").toString()).name(row.get("event_type").toString()).data(row.get("payload_json")));}catch(IOException ignored){}return e;}
 public void emit(String runId,String type,Object payload){try{long id=sequences.computeIfAbsent(runId,k->new AtomicLong(current(k))).incrementAndGet();String data=json.writeValueAsString(payload);jdbc.update("insert into run_events(id,event_id,workflow_run_id,event_type,payload_json,created_at) values(?,?,?,?,?,?)",UUID.randomUUID().toString(),id,runId,type,data,Instant.now().toString());for(SseEmitter e:clients.getOrDefault(runId,List.of()))try{e.send(SseEmitter.event().id(Long.toString(id)).name(type).data(data));}catch(Exception ex){e.complete();}}catch(Exception ignored){}}
 private long current(String run){Long n=jdbc.queryForObject("select coalesce(max(event_id),0) from run_events where workflow_run_id=?",Long.class,run);return n==null?0:n;}
}
